# 1. Physics Engine Class: `SpaceShip`

A simple representation of a spacecraft with position and mass.

```cpp
#include <glm/glm.hpp>
#include <memory>

class SpaceShip {
public:
    SpaceShip(double mass = 1.0)
        : m_mass(mass)
    {
        m_pos = glm::vec3(0.0f); // Initial position
        m_vel = glm::vec3(0.0f, 0.0f, 0.0f); // Initial velocity
        m_acc = glm::vec3(0.0f); // Current acceleration
    }

    // Update position and velocity
    void update() {
        m_pos += m_vel;
        m_vel += m_acc;
    }

    // Set or compute gravitational force based on F = G*m1*m2/r^3
    void setGravitationalForce(const std::shared_ptr<SpaceShip>& other, double G) {
        double distance = glm::distance(m_pos, other->m_pos);
        // Assuming masses are in kilograms
        float currentForce = G * m_mass * other->m_mass / distance * distance * distance * distance;
        // F = G*m1*m2/r^3, so divide by r^3 not just r^2
        m_acc -= currentForce * glm::vec3(
            (other->m_pos - m_pos) / distance,
            (other->m_pos - m_pos) / distance,
            (other->m_pos - m_pos) / distance
        );
    }

    double m_mass;

    glm::vec3 m_pos, m_vel, m_acc;
};
```

