        // Compute force for this pair between current ship and other
        float dist = glm::distance(m_ship->m_pos, other->m_pos);
        float force = G * m_ship->m_mass * other->m_mass / pow(dist, 3.0f);
        m_ship->setGravitationalForce(other, force);

        // Accumulate force on the other ship
