import math
import numpy as np

class EscapeVelocityCalculator:
    def __init__(self, force: float):
        self.force = force

    def calc_escape_velocity(self, mass: float, radius: float):
        G = 6.67430e-11  # Gravitational constant in m^3 kg^-1 s^-2
        if radius <= 0:
            raise ValueError("Radius must be greater than zero")

        # The escape velocity equation is derived from the gravitational force law F = G(m1*m2)/r^3
        F = self.force  # Force to escape
        m = mass        # Mass of the celestial body (kg)
        r = radius      # Distance from the center of the celestial body (m)

        # Solve for v escape: F = m*v^2/r = (1/2)*m*v^2/r = G*m*m/(r^4)
        v = math.sqrt((2 * F * radius) / mass)

        return v

def main():
    # Our base gravity assumption
    force = 1.0  # Arbitrary base force

    calculator = EscapeVelocityCalculator(force)

    celestial_database = {
        "Earth": {"mass": 5.972e24, "radius": 6.371e6},
        "Mars": {"mass": 6.39e23, "radius": 3.3902e6},
        "Moon": {"mass": 7.342e22, "radius": 1.737e6},
        "Europa": {"mass": 4.8e22, "radius": 1560.2e3},
        "Titan": {"mass": 1.230e23, "radius": 2574.3e3}
    }

    results = {}
    for name, info in celestial_database.items():
        v = calculator.calc_escape_velocity(info["mass"], info["radius"])
        results[name] = round(v, 3)

    print("Escape velocities for various celestial bodies:")
    for planet, v in results.items():
        print(f"{planet}: {v} m/s")

